    events: { title: ['实时事件','Live Event Feed'], eyebrow: ['热度与证据','ATTENTION & EVIDENCE'], interval: 12000 },
    tokens: { title: ['Token 发现','Token Discovery'], eyebrow: ['链上与叙事','ON-CHAIN / NARRATIVE'], interval: 15000 },
    decisions: { title: ['候选与决策','Candidates / Decisions'], eyebrow: ['确定性排名','DETERMINISTIC RANKING'], interval: 15000 },
    portfolio: { title: ['Paper 组合','Paper Portfolio'], eyebrow: ['模拟持仓','SIMULATED POSITIONS'], interval: 15000 },
