  const E = Object.fromEntries(['page-content','page-title','primary-nav','runtime-pill','mode-pill','last-sync','system-notice','refresh-button','sidebar','sidebar-scrim','mobile-menu','detail-drawer','drawer-scrim','drawer-title','drawer-eyebrow','drawer-content','drawer-close','toast-stack','language-switch'].map(id => [id, document.getElementById(id)]));

